const {test}=require('node:test'),assert=require('node:assert/strict');
const {mediaHarness,mediaSnapshot,roomState,deferred,json}=require('./helpers/media-browser.cjs');
const {mediaAudioHarness}=require('./helpers/media-audio-browser.cjs');
const music=(id='music-a')=>({id,type:'music',title:'歌曲A',trackId:'track-a',durationSec:180,requestedById:'member',requestedByName:'點播的朋友'});
const queued=(id,type='music')=>({...music(id),type,...(type==='video'?{videoId:'M7lc1UVf-VE',title:'YouTube影片'}:{})});
const posts=f=>f.network.filter(request=>request.body),gets=f=>f.network.filter(request=>request.route.startsWith('/api/room-media?'));
function mutable(initial,options={}){let state=structuredClone(initial);const f=mediaHarness({...options,fetchHandler:async request=>{if(request.route==='/api/music')return json({tracks:[{id:'track-a',title:'歌曲A',author:'作者'}]});if(request.body){const body=request.body;state={...state,revision:state.revision+1};if(body.action==='reorder')state.queue=body.orderIds.map(id=>state.queue.find(item=>item.id===id));if(body.action==='remove')state.queue=state.queue.filter(item=>item.id!==body.itemId);if(body.action==='duration')state.current={...state.current,durationSec:body.durationSec};if(body.action==='pause'||body.action==='play')state.playback={...state.playback,state:body.action==='play'?'playing':'paused'};if(body.action==='seek')state.playback={...state.playback,anchorPositionSec:body.positionSec};}return json(state);}});return {f,get:()=>state,set:next=>{state=structuredClone(next);}};}
async function realQueueRace(options={}){
 const first=mediaSnapshot({current:music(),playback:{state:'playing',anchorPositionSec:0,anchorServerMs:100000,rate:1}}),next=mediaSnapshot({...first,revision:2,queue:[queued('next')]}),wait=deferred();let reads=0;const f=mediaAudioHarness({...options,fetchHandler:request=>request.route==='/api/music'?json({tracks:[]}):++reads<3?json(first):wait.promise});
 await f.update(roomState(first));await f.click('mediaConsentDecline');await f.open();await f.click('mediaResume');await f.flushMediaEvents();const clip=f.audioClips[0];f.hide(true);await f.update(roomState(next));f.hide(false);await f.flush();return {f,clip,first,next,wait};
}
test('first room context fetches once even closed; unchanged markers and local timeline ticks never poll',async()=>{
 const initial=mediaSnapshot({current:null}),{f,set}=mutable(initial,{youtube:false});await f.update(roomState(initial,{media:null}));assert.equal(gets(f).length,1);assert.equal(f.node('tableMedia').open,false);assert.equal(f.node('tableMediaConsent').open,true);
 await f.click('mediaConsentDecline');for(let index=0;index<8;index++)await f.update(roomState(initial));await f.advance(10000);assert.equal(gets(f).length,1);assert.equal(f.thirdParty.length,0);
 await f.open();assert.equal(gets(f).length,2);assert.equal(f.network.filter(request=>request.route==='/api/music').length,1);await f.advance(5000);assert.equal(gets(f).length,2);
 const next=mediaSnapshot({current:null,revision:2});set(next);await f.update(roomState(next));assert.equal(gets(f).length,3);assert.equal(f.node('tableMediaConsent').open,false);
});
test('declining video loads no Google script or iframe; explicit later acceptance permits only the current video',async()=>{
 const initial=mediaSnapshot(),{f,set}=mutable(initial,{youtube:false});await f.update(roomState(initial));assert.equal(f.thirdParty.length,0);assert.equal(f.node('mediaPlayer').children.length,0);await f.click('mediaConsentDecline');await f.open();assert.equal(f.thirdParty.length,0);
 const next=mediaSnapshot({revision:2,current:{...initial.current,id:'video-b',videoId:'bZb4Zj7MfK0'}});set(next);await f.update(roomState(next));assert.equal(f.thirdParty.length,0);await f.click('mediaVideoJoin');assert.equal(f.thirdParty.length,1);f.installYT();await f.flush();assert.equal(f.players.length,1);assert.match(f.players[0].iframe.src,/bZb4Zj7MfK0/);assert.doesNotMatch(f.players[0].iframe.src,/M7lc1UVf-VE/);
});
test('room consent waits for hidden pages and existing game modals and is not shown again for the same seat',async()=>{
 const f=mediaHarness();const modal=f.otherModal();await f.update(roomState());assert.equal(f.node('tableMediaConsent').open,false);modal.close();f.emitMutations([{target:modal}]);assert.equal(f.node('tableMediaConsent').open,true);await f.click('mediaConsentDecline');await f.update(roomState());assert.equal(f.node('tableMediaConsent').open,false);
 const hidden=mediaHarness();hidden.hide(true);await hidden.update(roomState());assert.equal(hidden.node('tableMediaConsent').open,false);hidden.hide(false);assert.equal(hidden.node('tableMediaConsent').open,true);
});
test('mixed queue shows server titles, requester and type; members can enqueue but cannot reorder or transport',async()=>{
 const state=mediaSnapshot({isHost:false,canControl:false,canManageQueue:false,myPlayerId:'guest',queue:[queued('song'),queued('clip','video')]}),{f}=mutable(state);await f.update(roomState(state));await f.click('mediaConsentDecline');await f.open();
 const rows=f.node('mediaQueue').children;assert.equal(rows.length,2);assert.match(rows[0].getAttribute('aria-label'),/歌曲A.*歌曲.*點播的朋友/);assert.match(rows[1].getAttribute('aria-label'),/YouTube影片.*影片/);assert.equal(rows[0].draggable,false);assert.equal(f.node('mediaPlay').disabled,true);assert.equal(f.node('mediaPublishPosition').hidden,true);
 rows[0].querySelector('.table-media-drag-handle').onkeydown({target:rows[0].querySelector('.table-media-drag-handle'),key:'ArrowDown',preventDefault(){}});assert.equal(posts(f).length,0);f.node('mediaTrack').value='track-a';await f.submit('mediaMusicForm');assert.equal(posts(f).length,1);assert.equal(posts(f)[0].body.action,'enqueue');assert.equal(posts(f)[0].body.type,'music');
});
test('same-revision room permissions immediately promote and demote media controls',async()=>{
 const state=mediaSnapshot({isHost:false,canControl:false,canManageQueue:false,myPlayerId:'guest'}),{f}=mutable(state);await f.update(roomState(state));await f.click('mediaConsentDecline');assert.equal(f.node('mediaPlay').disabled,true);const count=gets(f).length;
 await f.update(roomState(state,{permissions:{role:'manager',canManageMedia:true,isHost:false}}));assert.equal(f.node('mediaPlay').disabled,false);assert.equal(f.node('mediaPublishPosition').hidden,false);assert.equal(f.node('mediaPublishPosition').disabled,true);assert.equal(gets(f).length,count);
 await f.update(roomState(state,{permissions:{role:'member',canManageMedia:false,isHost:false}}));assert.equal(f.node('mediaPlay').disabled,true);assert.equal(f.node('mediaPublishPosition').hidden,true);await f.node('mediaPublishPosition').onclick();await f.flush();assert.equal(posts(f).length,0);
});
test('manager keyboard and drag ordering send the complete current queue and expected revision once',async()=>{
 const initial=mediaSnapshot({queue:[queued('a'),queued('b'),queued('c')]}),{f}=mutable(initial);await f.update(roomState(initial));await f.click('mediaConsentDecline');await f.open();await f.openPlaylist();const middle=f.node('mediaQueue').children[1].querySelector('.table-media-drag-handle');middle.focus();middle.onkeydown({target:middle,key:'ArrowUp',preventDefault(){}});await f.flush();assert.deepEqual(posts(f)[0].body.orderIds,['b','a','c']);assert.equal(posts(f)[0].body.expectedRevision,1);assert.equal(f.document.activeElement,f.node('mediaQueue').children[0].querySelector('.table-media-drag-handle'));
 const row=f.node('mediaQueue').children[1],source=f.node('mediaQueue').children[2],transfer={setData(){},getData:()=> 'c'};source.querySelector('.table-media-drag-handle').ondragstart({preventDefault(){},dataTransfer:transfer});row.ondrop({preventDefault(){},dataTransfer:transfer});await f.flush();assert.deepEqual(posts(f)[1].body.orderIds,['b','c','a']);assert.equal(posts(f)[1].body.expectedRevision,2);assert.match(posts(f)[1].body.requestId,/^[a-f0-9-]{36}$/);assert.equal(posts(f)[1].body.roomInstanceId,'room-a');assert.equal(posts(f)[1].body.playbackSessionId,'session-a');
});
test('stale reorder adopts the server queue and leaves it for confirmation without automatically replaying the old order',async()=>{
 const initial=mediaSnapshot({queue:[queued('a'),queued('b')]}),newer=mediaSnapshot({revision:3,queue:[queued('a'),queued('b'),queued('other')]}),f=mediaHarness({fetchHandler:async request=>request.body?json({error:'stale',state:newer},{ok:false,status:409}):json(initial)});await f.update(roomState(initial));await f.click('mediaConsentDecline');const row=f.node('mediaQueue').children[1].querySelector('.table-media-drag-handle');row.onkeydown({target:row,key:'ArrowUp',preventDefault(){}});await f.flush();assert.equal(posts(f).length,1);assert.deepEqual(f.node('mediaQueue').children.map(item=>item.dataset.itemId),['a','b','other']);assert.match(f.node('mediaStatus').textContent,/確認/);
});
test('music to video to music stops the opposite player, including late Audio.play and old YouTube ready callbacks',async()=>{
 const first=mediaSnapshot({current:music(),playback:{state:'playing',anchorPositionSec:0,anchorServerMs:100000,rate:1}}),{f,set}=mutable(first,{pendingAudio:true,enabled:true});await f.update(roomState(first));await f.click('mediaConsentAccept');await f.open();await f.click('mediaResume');const old=f.audioClips[0];assert.ok(old.resolvePlay);
 const video=mediaSnapshot({revision:2});set(video);await f.update(roomState(video));assert.equal(old.paused,true);assert.equal(old.src,undefined);assert.equal(f.players.length,1);const previousVideo=f.players[0];previousVideo.ready();
 const final=mediaSnapshot({revision:3,current:music('music-b'),playback:first.playback});set(final);await f.update(roomState(final));assert.equal(previousVideo.destroyed,true);const fresh=f.audioClips.at(-1);assert.notEqual(fresh,old);fresh.resolvePlay();await f.flush();assert.equal(fresh.paused,false);old.resolvePlay();previousVideo.ready();await f.flush();assert.equal(old.paused,true);assert.equal(fresh.paused,false);assert.equal(f.players.length,1);
});
test('successive videos retire the old player even after the shared API has already loaded',async()=>{
 const initial=mediaSnapshot(),{f,set}=mutable(initial);await f.update(roomState(initial));await f.click('mediaConsentAccept');const old=f.players[0];old.ready();const next=mediaSnapshot({revision:2,current:{...initial.current,id:'next-video',videoId:'bZb4Zj7MfK0'},playbackSessionId:'session-b'});set(next);await f.update(roomState(next));assert.equal(old.destroyed,true);assert.equal(f.players.length,2);old.ready();assert.equal(f.players[1].destroyed,false);assert.match(f.players[1].iframe.src,/bZb4Zj7MfK0/);
});
test('pending API load cannot create an old iframe after the room changes or the current becomes music',async()=>{
 const first=mediaSnapshot(),{f,set}=mutable(first,{youtube:false});await f.update(roomState(first));await f.click('mediaConsentAccept');assert.equal(f.thirdParty.length,1);
 const next=mediaSnapshot({revision:2,current:music()});set(next);await f.update(roomState(next));f.installYT();await f.flush();assert.equal(f.players.length,0);assert.equal(f.node('mediaPlayer').children.length,0);assert.equal(f.audioClips.length,1);
 const other=mediaSnapshot({roomInstanceId:'room-b',myPlayerId:'other-seat',current:null});set(other);await f.update(roomState(other,{code:'DEF456'}));assert.equal(f.node('tableMediaConsent').open,true);assert.equal(f.audioClips[0].src,undefined);
});
test('blocked music and YouTube retain native retry and local close without an app external-video option',async()=>{
 const musicState=mediaSnapshot({current:music(),playback:{state:'playing',anchorPositionSec:0,anchorServerMs:100000,rate:1}}),{f}=mutable(musicState,{blockedAudio:true,enabled:true});await f.update(roomState(musicState));await f.click('mediaConsentDecline');await f.open();await f.click('mediaResume');assert.equal(f.audioClips[0].controls,true);assert.match(f.node('mediaPlaybackStatus').textContent,/原生播放/);
 const v=mediaHarness();await v.update(roomState());await v.click('mediaConsentAccept');const player=v.players[0];player.ready();player.blocked();assert.match(v.node('mediaPlaybackStatus').textContent,/在自己的裝置播放/);assert.match(player.iframe.src,/controls=1/);assert.match(player.iframe.getAttribute('allow'),/autoplay/);
 for(const error of [101,150,153]){player.error(error);assert.equal(v.node('mediaNativeVideo').hidden,false);assert.equal(v.node('mediaVideoExit').hidden,false);assert.match(v.node('mediaPlaybackStatus').textContent,/原生播放器.*關閉自己的影片/);assert.doesNotMatch(v.node('mediaPlaybackStatus').textContent,/在\s*YouTube\s*開啟/);}await v.update(roomState());assert.equal(v.node('mediaNativeVideo').hidden,false);await v.click('mediaNativeVideo');assert.equal(player.destroyed,true);assert.doesNotMatch(v.node('mediaPlayer').children[0].src,/enablejsapi/);assert.equal(v.document.querySelector('#mediaYouTubeLink'),null);await v.click('mediaVideoExit');assert.equal(v.node('mediaPlayer').children.length,0);assert.equal(v.node('tableMedia').open,true);assert.equal(posts(v).length,0);
});
test('paused alignment uses cue then pause; local native playback changes do not send shared transport commands',async()=>{
 const f=mediaHarness();await f.update(roomState());await f.click('mediaConsentAccept');const player=f.players[0];player.ready();assert.equal(player.calls.at(-1)[0],'pause');assert.ok(player.calls.some(call=>call[0]==='cue'&&call[1].startSeconds===12));
 player.state(1);player.state(2);player.state(3);await f.advance(3000);assert.equal(posts(f).length,0);await f.click('mediaAlign');assert.equal(posts(f).length,0);assert.equal(player.calls.at(-1)[0],'pause');
});
test('same-revision music resumes only its visibility interruption at the current anchor without network traffic or restored privileges',async()=>{
 const state=mediaSnapshot({current:music(),playback:{state:'playing',anchorPositionSec:12,anchorServerMs:100000,rate:1}}),{f}=mutable(state);await f.update(roomState(state));await f.click('mediaConsentDecline');await f.open();await f.click('mediaResume');const clip=f.audioClips[0],requests=f.network.length;let plays=0,checkpoints=0;const play=clip.play.bind(clip);clip.play=()=>{clip.paused?plays++:checkpoints++;return play();};assert.equal(clip.paused,false);
 f.hide(true);assert.equal(clip.paused,true);await f.advance(5000);await f.update(roomState(state,{permissions:{role:'member',canManageMedia:false,isHost:false}}));f.hide(false);await f.flush();assert.equal(clip.paused,false);assert.equal(clip.currentTime,17);assert.equal(f.audioClips.length,1);assert.equal(plays,1);assert.equal(checkpoints,1);assert.equal(f.network.length,requests);assert.equal(f.node('mediaPlay').disabled,true);assert.equal(f.node('mediaPublishPosition').hidden,true);assert.equal(posts(f).length,0);
 f.hide(false);await f.flush();assert.equal(plays,1,'duplicate visible events do not start another play');
});
test('visibility does not override native music pause, disabled sound, ungranted playback, shared pause or an empty current',async()=>{
 for(const condition of ['native-pause','sound-disabled','not-unlocked','browser-blocked','shared-paused','empty']){
  const state=mediaSnapshot({current:condition==='empty'?null:music(),playback:{state:'playing',anchorPositionSec:0,anchorServerMs:100000,rate:1}}),{f,set}=mutable(state,{enabled:true,blockedAudio:condition==='browser-blocked'});await f.update(roomState(state));await f.click('mediaConsentDecline');if(condition!=='not-unlocked')await f.open();if(!['not-unlocked','empty'].includes(condition))await f.click('mediaResume');const clip=f.audioClips[0];if(condition==='native-pause')clip.pause();
  f.hide(true);if(condition==='sound-disabled')f.window.AudioSettings.set('music',{enabled:false},{});if(condition==='shared-paused'){const next=mediaSnapshot({...state,revision:2,playback:{...state.playback,state:'paused'}});set(next);await f.update(roomState(next));}const requests=f.network.length;f.hide(false);await f.flush();assert.equal(clip?.paused??true,true,condition);assert.equal(f.network.length,requests,condition);assert.equal(posts(f).length,0,condition);if(condition==='sound-disabled')assert.equal(clip.muted,true);if(condition==='browser-blocked')assert.match(f.node('mediaPlaybackStatus').textContent,/原生播放/);
 }
});
test('an interrupted music player waits for the current room marker and resumes from a fresh same-playback reply only',async()=>{
 const first=mediaSnapshot({current:music(),playback:{state:'playing',anchorPositionSec:0,anchorServerMs:100000,rate:1}}),wait=deferred();let count=0;const f=mediaHarness({fetchHandler:request=>request.route==='/api/music'?json({tracks:[]}):++count===1?json(first):wait.promise});await f.update(roomState(first));await f.click('mediaConsentDecline');await f.click('mediaResume');const clip=f.audioClips[0];f.hide(true);const next=mediaSnapshot({...first,revision:2,queue:[queued('next')]});await f.update(roomState(next));const requests=f.network.length;f.hide(false);await f.flush();assert.equal(clip.paused,true,'the stale playing snapshot cannot restart music');assert.equal(f.network.length,requests);wait.resolve(json(next));await f.flush();assert.equal(clip.paused,false);assert.equal(f.audioClips.length,1);assert.equal(f.network.length,requests);assert.equal(posts(f).length,0);
});
test('real preview binding preserves a newer native Play then Pause while a queue-only visibility refresh is pending',async()=>{
 const first=mediaSnapshot({current:music(),playback:{state:'playing',anchorPositionSec:0,anchorServerMs:100000,rate:1}}),next=mediaSnapshot({...first,revision:2,queue:[queued('next')]}),wait=deferred();let reads=0;const f=mediaAudioHarness({fetchHandler:request=>request.route==='/api/music'?json({tracks:[]}):++reads<3?json(first):wait.promise});
 await f.update(roomState(first));await f.click('mediaConsentDecline');await f.open();await f.click('mediaResume');await f.flushMediaEvents();const clip=f.audioClips[0];assert.equal(clip.paused,false);assert.equal(f.window.AudioSettings.get().music.enabled,true);assert.equal(f.node('mediaMusicNative').hidden,false);assert.equal(f.node('tableMedia').open,true);
 f.hide(true);await f.flushMediaEvents();await f.update(roomState(next));f.hide(false);await f.flush();assert.equal(clip.paused,true);assert.equal(f.network.length,4);await clip.nativePlay();await f.flushMediaEvents();clip.nativePause();await f.flushMediaEvents();assert.equal(clip.paused,true,'the new native Pause precedes the delayed reply');wait.resolve(json(next));await f.flush();await f.flushMediaEvents();assert.equal(f.audioClips[0],clip);assert.equal(f.audioClips.length,1);assert.equal(f.node('mediaMusicNative').hidden,false);assert.equal(clip.paused,true,'queue-only state cannot restore an obsolete visibility intent');assert.equal(f.network.length,4);assert.equal(posts(f).length,0);
});
test('late trusted programmatic media events cannot cancel or prematurely fulfill a valid visibility interruption',async()=>{
 const{f,clip,next,wait}=await realQueueRace();assert.equal(clip.paused,true);assert.equal(f.network.length,4);await f.flushMediaEvents();assert.equal(clip.paused,true,'our queued background Pause is not a native choice');const plays=clip.plays;wait.resolve(json(next));await f.flush();await f.flushMediaEvents();assert.equal(clip.paused,false);assert.equal(clip.plays,plays+1);assert.equal(f.audioClips.length,1);assert.equal(f.network.length,4);assert.equal(posts(f).length,0);
});
test('native Play and Pause queued together cannot be converted into another play by the actual preview settings listener',async()=>{
 const{f,clip,next,wait}=await realQueueRace();const plays=clip.plays;await clip.nativePlay();clip.nativePause();await f.flushMediaEvents();assert.equal(clip.paused,true);assert.equal(clip.plays,plays,'the late native Play event cannot reenter alignAudio');wait.resolve(json(next));await f.flush();await f.flushMediaEvents();assert.equal(clip.paused,true);assert.equal(clip.plays,plays);assert.equal(f.network.length,4);assert.equal(f.window.AudioSettings.get().music.enabled,true);
});
test('native control pointer and key interaction invalidate visibility intent before asynchronously queued media events',async()=>{
 for(const type of ['pointerdown','keydown']){const{f,clip,next,wait}=await realQueueRace();let prevented=0;clip.dispatch(type,{type,target:clip,key:' ',preventDefault(){prevented++;}});await clip.nativePlay();clip.nativePause();wait.resolve(json(next));await f.flush();assert.equal(clip.paused,true,type);await f.flushMediaEvents();assert.equal(clip.paused,true,type);assert.equal(prevented,0);assert.equal(f.network.length,4);assert.equal(posts(f).length,0);}
});
for(const pendingAudio of [false,true])for(const ownPauseProcessed of [false,true])test('queue reply preceding uncaptured native Play/Pause preserves Pause: pending='+pendingAudio+', owned pause processed='+ownPauseProcessed,async()=>{
 const{f,clip,next,wait}=await realQueueRace({pendingAudio});if(ownPauseProcessed)await f.flushMediaEvents();assert.equal(clip.paused,true);assert.equal(f.network.length,4);await clip.nativePlay();clip.nativePause();assert.equal(clip.paused,true,'the newer native Pause has already changed the same Audio');wait.resolve(json(next));await f.flush();await f.flushMediaEvents();if(pendingAudio){clip.resolvePlay();await f.flush();await f.flushMediaEvents();}assert.equal(clip.paused,true,'the older visibility restore must not win over the queued native choice');assert.equal(f.audioClips[0],clip);assert.equal(f.audioClips.length,1);assert.equal(f.node('tableMedia').open,true);assert.equal(f.node('mediaMusicNative').hidden,false);assert.equal(f.window.AudioSettings.get().music.enabled,true);assert.equal(f.network.length,4);assert.equal(posts(f).length,0);
});
test('uncaptured native Play/Pause/Play before the reply keeps the final local Play and native position',async()=>{
 const{f,clip,next,wait}=await realQueueRace();await f.flushMediaEvents();clip.currentTime=37;await clip.nativePlay();clip.nativePause();await clip.nativePlay();assert.equal(clip.paused,false);wait.resolve(json(next));await f.flush();await f.flushMediaEvents();assert.equal(clip.paused,false);assert.equal(clip.currentTime,37,'the native Play supersedes visibility restoration without a seek');assert.equal(clip.plays,1);assert.equal(f.network.length,4);assert.equal(posts(f).length,0);
});
