test('header release clears its gesture before a synchronous lost-capture callback and saves once',async()=>{
 const f=mediaHarness();await f.update(roomState());await f.click('mediaConsentDecline');await f.open();await f.flushFrames();const bar=f.node('mediaWindowBar'),release=bar.releasePointerCapture.bind(bar),write=f.context.localStorage.setItem;let saves=0;
 bar.releasePointerCapture=id=>{release(id);bar.onlostpointercapture(pointer(id,80,80));};f.context.localStorage.setItem=(key,value)=>{if(key==='bga.media.window.v1')saves++;write(key,value);};bar.onpointerdown(pointer(1,100,100,{target:bar,isPrimary:true}));bar.onpointermove(pointer(1,80,80));bar.onpointerup(pointer(1,80,80));assert.equal(bar.hasPointerCapture(1),false);assert.equal(saves,1);
});

