test('keyboard resize reads native DOMRect prototype accessors rather than spreading nonenumerable geometry',async()=>{
 const f=mediaHarness();f.window.innerHeight=1109;await f.update(roomState());await f.click('mediaConsentAccept');f.players[0].ready();await f.flushFrames();const dialog=f.node('tableMedia'),original=dialog.getBoundingClientRect.bind(dialog),player=f.players[0],iframe=player.iframe,network=f.network.length;
 class NativeRect{#box;constructor(box){this.#box=box;}get left(){return this.#box.left;}get top(){return this.#box.top;}get width(){return this.#box.width;}get height(){return this.#box.height;}get right(){return this.left+this.width;}get bottom(){return this.top+this.height;}}
 dialog.getBoundingClientRect=()=>new NativeRect(original());assert.deepEqual(Object.keys(dialog.getBoundingClientRect()),[]);
 const before=dialog.getBoundingClientRect();for(const [edge,key]of [['n','ArrowDown'],['s','ArrowUp'],['w','ArrowRight'],['e','ArrowLeft'],['nw','ArrowDown'],['ne','ArrowDown'],['sw','ArrowUp'],['se','ArrowUp']])dialog.querySelector('.media-resize-'+edge).onkeydown({key,preventDefault(){}});
 await f.flushFrames();const after=dialog.getBoundingClientRect();assert.equal(after.width,before.width-40);assert.equal(after.height,before.height-120);assert.equal(player.iframe,iframe);assert.equal(f.players.length,1);assert.equal(f.network.length,network);assert.ok(Number.isFinite(JSON.parse(f.storage.get('bga.media.size.v1')).height));assert.equal(posts(f).length,0);
});

test('only a manager explicit publish reads native video time and sends one identity-bound seek',async()=>{
 const {f}=mutable(mediaSnapshot());await f.update(roomState());await f.click('mediaConsentAccept');const player=f.players[0];let time=12,reads=0;player.getCurrentTime=()=>{reads++;return time;};player.ready();const button=f.node('mediaPublishPosition');assert.equal(button.hidden,false);assert.equal(button.disabled,false);assert.equal(button.dataset.uiIcon,'send');assert.equal(f.node('mediaAlign').dataset.uiIcon,'sync');assert.equal(button.getAttribute('aria-label'),'同步我的播放進度');assert.equal(f.document.querySelector('#mediaSeek'),null);
 time=72.5;player.state(2);await f.advance(2500);assert.equal(reads,0);assert.equal(posts(f).length,0);await f.click('mediaPublishPosition');assert.equal(reads,1);const seek=posts(f)[0].body;assert.equal(seek.action,'seek');assert.equal(seek.positionSec,72.5);assert.equal(seek.expectedRevision,1);assert.equal(seek.roomInstanceId,'room-a');assert.equal(seek.playbackSessionId,'session-a');assert.equal(posts(f).length,1);
 const guest=mediaSnapshot({myPlayerId:'guest',isHost:false,canControl:false,canManageQueue:false}),{f:member}=mutable(guest);await member.update(roomState(guest));await member.click('mediaConsentAccept');member.players[0].getCurrentTime=()=>33;member.players[0].ready();assert.equal(member.node('mediaPublishPosition').hidden,true);await member.node('mediaPublishPosition').onclick();await member.click('mediaAlign');assert.equal(posts(member).length,0);
});

test('music native seeking stays local until explicit publish and unreadable media has accessible reasons',async()=>{
 const state=mediaSnapshot({current:music()}),{f}=mutable(state);await f.update(roomState(state));await f.click('mediaConsentDecline');await f.open();const clip=f.audioClips[0];clip.currentTime=45.75;await f.advance(2500);assert.equal(posts(f).length,0);assert.equal(f.node('mediaPublishPosition').disabled,false);await f.click('mediaPublishPosition');assert.equal(posts(f)[0].body.action,'seek');assert.equal(posts(f)[0].body.positionSec,45.75);
 clip.readyState=0;await f.advance(500);assert.equal(f.node('mediaPublishPosition').disabled,true);assert.equal(f.node('mediaPublishPosition').getAttribute('aria-describedby'),'mediaPublishHint');assert.match(f.node('mediaPublishHint').textContent,/歌曲.*準備/);
 const v=mediaHarness();await v.update(roomState());await v.click('mediaConsentAccept');const player=v.players[0];player.getCurrentTime=()=>24;assert.equal(v.node('mediaPublishPosition').disabled,true);assert.match(v.node('mediaPublishHint').textContent,/影片.*準備/);player.ready();assert.equal(v.node('mediaPublishPosition').disabled,false);player.error(101);await v.click('mediaNativeVideo');assert.equal(v.node('mediaPublishPosition').disabled,true);assert.match(v.node('mediaPublishHint').textContent,/原生.*無法讀取/);await v.node('mediaPublishPosition').onclick();assert.equal(posts(v).length,0);
});

test('publish rejects nonnumeric, nonfinite, negative and excessive local positions without a seek',async()=>{
 const {f}=mutable(mediaSnapshot());await f.update(roomState());await f.click('mediaConsentAccept');const player=f.players[0];player.getCurrentTime=()=>0;player.ready();for(const value of [undefined,null,'12',NaN,Infinity,-1,100.1,14401]){player.getCurrentTime=()=>value;await f.click('mediaPublishPosition');assert.equal(posts(f).length,0);assert.match(f.node('mediaPlaybackStatus').textContent,/有效.*進度/);}
 player.getCurrentTime=()=>{throw Error('player unavailable');};await f.click('mediaPublishPosition');assert.equal(posts(f).length,0);assert.match(f.node('mediaPlaybackStatus').textContent,/讀取.*重試/);player.getCurrentTime=()=>0;await f.click('mediaPublishPosition');assert.equal(posts(f)[0].body.positionSec,0);
});

test('late native time reads cannot seek a new session, room, demoted role, closed or hidden player, or another command',async()=>{
 for(const change of ['session','revision','room','demotion','close','hidden','native','command']){const first=mediaSnapshot(),{f,set}=mutable(first);await f.update(roomState(first));await f.click('mediaConsentAccept');const wait=deferred(),player=f.players[0];player.getCurrentTime=()=>wait.promise;player.ready();const pending=f.node('mediaPublishPosition').onclick();await f.flush();assert.equal(f.node('mediaPublishPosition').disabled,true);
  if(change==='session'||change==='revision'){const next=mediaSnapshot({revision:2,...(change==='session'?{playbackSessionId:'session-b'}:{queue:[queued('new')]})});set(next);await f.update(roomState(next));}else if(change==='room'){const next=mediaSnapshot({roomInstanceId:'room-b',myPlayerId:'other-seat'});set(next);await f.update(roomState(next,{code:'DEF456'}));}else if(change==='demotion')await f.update(roomState(first,{permissions:{role:'member',canManageMedia:false,isHost:false}}));else if(change==='close')await f.click('mediaClose');else if(change==='hidden')f.hide(true);else if(change==='native'){player.error(101);await f.click('mediaNativeVideo');}else await f.click('mediaPlay');
  wait.resolve(77);await pending;await f.flush();assert.equal(posts(f).filter(request=>request.body.action==='seek').length,0,change);
 }
});

test('a timed out read releases its own job and a late value cannot clear or send the newer pending read',async()=>{
 const {f}=mutable(mediaSnapshot());await f.update(roomState());await f.click('mediaConsentAccept');const old=deferred(),fresh=deferred(),player=f.players[0];player.getCurrentTime=()=>old.promise;player.ready();const first=f.node('mediaPublishPosition').onclick();await f.advance(2001);await first;assert.equal(f.node('mediaPublishPosition').disabled,false);assert.match(f.node('mediaPlaybackStatus').textContent,/讀取.*重試/);
 player.getCurrentTime=()=>fresh.promise;const second=f.node('mediaPublishPosition').onclick();await f.flush();old.resolve(33);await f.flush();assert.equal(f.node('mediaPublishPosition').disabled,true);assert.equal(posts(f).length,0);fresh.resolve(44);await second;assert.equal(posts(f).length,1);assert.equal(posts(f)[0].body.positionSec,44);assert.equal(f.node('mediaPublishPosition').disabled,false);
 const css=require('node:fs').readFileSync(require('node:path').join(__dirname,'../public/shared/table-media.css'),'utf8');assert.match(css,/@media\s*\(min-width:621px\)\s*and\s*\(pointer:fine\)/);assert.match(css,/\.media-video-active #mediaControlRow[^}]*--media-control-size:calc\(var\(--ui-control-height,44px\)\s*\*\s*\.81818\)/);assert.match(css,/#mediaControlRow \.ui-icon-button\{[^}]*min-width:var\(--media-control-size\)[^}]*min-height:var\(--media-control-size\)/);assert.match(css,/#mediaControlRow \.ui-icon\{[^}]*width:var\(--media-icon-size\)/);
});
